function validate([nums, k, edges]) {
  const n = nums.length;
  if (n < 2 || n > 20000) return 'nums needs 2 to 2 * 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value in nums is an integer from 0 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is an integer from 1 to 10^9.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges needs exactly n - 1 edges.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge endpoints are node labels from 0 to n - 1.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree (no cycles or repeated edges).';
    root[a] = b;
  }
  return null;
}

