function maximumValueSum(nums, k, edges) {
  let total = 0;
  let flips = 0;
  let smallestLoss = Infinity;
  for (const value of nums) {
    const flipped = value ^ k;
    total += Math.max(value, flipped);
    if (flipped > value) {
      flips++;
    }
    smallestLoss = Math.min(smallestLoss, Math.abs(flipped - value));
  }
  if (flips % 2 === 0) {
    return total;
  }
  return total - smallestLoss;
}

