function maximumValueSum(nums, k, edges) {
  // Using an edge twice cancels out, so try every subset of edges used once.
  let best = -1;
  for (let mask = 0; mask < (1 << edges.length); mask++) {
    const values = nums.slice();
    edges.forEach(([u, v], e) => {
      if (mask & (1 << e)) { values[u] ^= k; values[v] ^= k; }
    });
    best = Math.max(best, values.reduce((a, b) => a + b, 0));
  }
  return best;
}

