function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const big = size === 'large' || rand() < 0.3;
  const n = size === 'large' ? 2000 : int(2, 8);
  const top = big ? 1000000000 : 15;
  const k = int(1, big && rand() < 0.7 ? 1000000000 : 15);
  const nums = Array.from({ length: n }, () => int(0, top));
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const edges = [];
  for (let i = 1; i < n; i++) {
    const parent = order[int(0, i - 1)];
    edges.push(rand() < 0.5 ? [parent, order[i]] : [order[i], parent]);
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [nums, k, edges];
}
